'use strict';
function organicLots(t,count){const lots=[],city=t.kind==='city',radius=city?27:13;let seed=[...t.id].reduce((a,c)=>a*31+c.charCodeAt(0),7)>>>0;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let attempts=0;lots.length<count&&attempts<20000;attempts++){const angle=random()*Math.PI*2,r=Math.sqrt(random())*radius,x=Math.round(t.x+Math.cos(angle)*r-2),y=Math.round(t.y+Math.sin(angle)*r*.92-2);if(Math.hypot(x+2-t.x,y+2-t.y)<5)continue;if(t.capital&&x<t.x+8&&x+5>t.x-8&&y<t.y-19)continue;if(lots.some(([a,b])=>x<a+7.5&&x+7.5>a&&y<b+6.5&&y+6.5>b))continue;lots.push([x,y]);}if(lots.length!==count)throw new Error('Settlement layout could not fit '+t.id);return lots;}
const organicRoads=[];
function curveRoad(ax,az,bx,bz,width=1.1,paved=false){const dx=bx-ax,dz=bz-az,length=Math.hypot(dx,dz);if(length<.1)return;const bend=Math.min(6,length*.14)*Math.sin(ax*.3+az*.2+bx*.07),nx=-dz/length,nz=dx/length,steps=Math.max(2,Math.ceil(length/2));let last=[ax,az];for(let i=1;i<=steps;i++){const t=i/steps,offset=Math.sin(t*Math.PI)*bend,next=[ax+dx*t+nx*offset,az+dz*t+nz*offset];organicRoads.push({a:last,b:next,width,paved});last=next;}}
const terrainBeforeOrganic=expandedTerrain;
expandedTerrain=function(x,z){if(!inWorld())return terrainBeforeOrganic(x,z);return expandedWater(x,z)?3:0;};
const setupBeforeOrganic=setupExpandedWorld;
setupExpandedWorld=function(){const resume={scene:s.sceneId,x:s.x,y:s.y,scale:s.worldScale};setupBeforeOrganic();if(organicRoads.length)return;const world=worldScenes.overworld;expandPhysicalWorld(world);for(const [ax,az,bx,bz]of realmRoads)curveRoad(ax,az,bx,bz,1.15);for(const t of SETTLEMENTS){const local=world.buildings.filter(b=>b.settlement===t.id),junctions=[[t.x,t.y]];for(const b of local){const seg=Math.max(1,Math.round(b.w/2)),xx=b.x+(Math.floor(seg/2)+.5)*b.w/seg;b.service.x=Math.round(xx-.5);b.service.y=Math.round(b.y+b.h);const door=[b.service.x+.5,b.service.y+.5],join=junctions.reduce((best,p)=>Math.hypot(p[0]-door[0],p[1]-door[1])<Math.hypot(best[0]-door[0],best[1]-door[1])?p:best);curveRoad(...join,...door,.85,t.kind==='city');junctions.push(door);}}
 // Preserve the starter region's destination connections with winding paths.
 for(const [a,b]of [[[14,17],[14,35]],[[7,17],[36,17]],[[38,17],[55,17]],[[14,35],[36,35]],[[38,35],[55,35]],[[55,8],[55,46]],[[55,35],[75,61]],[[75,61],[90,71]]])curveRoad(...a.map(v=>v*3),...b.map(v=>v*3),1.2);
 populateWalkInRooms(world);landHeights.clear();landWater.clear();realmNavigation.clear();if(resume.scale===3&&resume.scene==='overworld')activateScene('overworld',resume.x,resume.y,false);
};
function roadSegmentDistance(x,z,seg){const dx=seg.b[0]-seg.a[0],dz=seg.b[1]-seg.a[1],t=Math.max(0,Math.min(1,((x-seg.a[0])*dx+(z-seg.a[1])*dz)/(dx*dx+dz*dz)));return Math.hypot(x-seg.a[0]-dx*t,z-seg.a[1]-dz*t);}
const realmCrossingsBeforeOrganic=drawRealmCrossings;
drawRealmCrossings=function(r){realmCrossingsBeforeOrganic(r);for(const seg of organicRoads){const x=(seg.a[0]+seg.b[0])/2,z=(seg.a[1]+seg.b[1])/2,q=project3(x,0,z);if(q.x< -100||q.x>screen.w+100||q.y< -100||q.y>screen.h+100||expandedWater(x,z)||buildings.some(b=>x>b.x&&x<b.x+b.w&&z>b.y&&z<b.y+b.h))continue;emitMesh3(r,cachedMesh3(seg,'prop',m=>{const dx=seg.b[0]-seg.a[0],dz=seg.b[1]-seg.a[1],len=Math.hypot(dx,dz),nx=-dz/len,nz=dx/len,edge=p=>seg.width*(1+.10*Math.sin(p[0]*2.3+p[1]*1.7)),a=seg.a,b=seg.b,wa=edge(a),wb=edge(b);m.face([[a[0]-nx*wa,.035,a[1]-nz*wa],[b[0]-nx*wb,.035,b[1]-nz*wb],[b[0]+nx*wb,.035,b[1]+nz*wb],[a[0]+nx*wa,.035,a[1]+nz*wa]],'#aa9167',null,seg.paved?16:15,null,[[0,0],[0,1],[1,1],[1,0]]);return .05;}));}
 for(const b of buildings){if(!b.service||b.archetype==='castle'||b.arch)continue;const q=project3(b.x,0,b.y);if(q.x< -150||q.x>screen.w+150||q.y< -200||q.y>screen.h+150)continue;const seg=Math.max(1,Math.round(b.w/2)),scale=b.w/seg/2,xx=b.x+(Math.floor(seg/2)+.5)*b.w/seg,open=b.service.openedAt===undefined?0:Math.min(1,(time-b.service.openedAt)/.35);rebuiltPlace(r,'Door_1_Round',xx-.53*scale,0,b.y+b.h+.04,scale,-open*Math.PI*.48);}
};
let doorReturnUntil=0;
const engageBeforeDoors=engage;
engage=function(o){if(o.type!=='door'||!o.destination)return engageBeforeDoors(o);const p=route(o.x,o.y,false);if(p===null){toast('There is no clear path to this door.');return;}o.openedAt=time;target=o;path=p;elapsed=0;renderAction();if(!p.length&&Math.hypot(px-o.x,py-o.y)<.05)arrive();};
openBuilding3=function(b){if(b.service?.destination)engage(b.service);};
const leaveBeforeDoors=leaveInterior;
leaveInterior=function(){doorReturnUntil=time+2;leaveBeforeDoors();};
function updateDoorThreshold(){if(!inWorld()||time<doorReturnUntil||target?.type==='door')return;const door=objects.find(o=>o.type==='door'&&o.destination&&o.openedAt!==undefined&&Math.hypot(px-o.x,py-o.y)<.18);if(door)enterInterior(door);}
